'use strict';

/**
 * Style CSS utilities for the MTD hero CTA stylegate integration.
 * Provides shared CSS utility functions used by the style registry and gate checks.
 */

const color = {
  white: '#FFFFFF',
  offWhite: 'rgba(255, 255, 255, 0.9)',
  darkCharcoal: '#212121',
  overDark: '#1A1A1A'
};

const spacing = {
  s: '8px',
  m: '16px',
  l: '24px'
};

const typography = {
  fontFamily: "'Inter', sans-serif",
  fontWeightNormal: 400,
  fontWeightBold: 700
};

function buttonStyle(variant) {
  if (variant === 'secondary') {
    return {
      color: color.white,
      background: 'transparent',
      border: '1px solid rgba(255, 255, 255, 0.6)',
      borderRadius: '999px',
      padding: `${spacing.m} ${spacing.l}`,
      fontWeight: typography.fontWeightBold,
      textDecoration: 'none'
    };
  }
  return {};
}

module.exports = { buttonStyle, color, spacing, typography };

