#!/usr/bin/env node
'use strict';
/**
 * add-pair — create or repair an account, and keep an access code and its
 * auth password in step.
 *
 *   node tooling/add-pair.js someone@sage.com            # generates a code
 *   node tooling/add-pair.js someone@sage.com 24681000   # or you choose it (8+ digits)
 *   node tooling/add-pair.js someone@sage.com --remove    # take access away
 *   node tooling/add-pair.js --list                      # who has access
 *   node tooling/add-pair.js --selftest                  # offline, no network
 *
 * WHY A COMMAND AND NOT AN ADMIN PAGE
 * Creating the Supabase account and moving its password need the service_role
 * key. Put that in a browser and it is in the page for anyone to read — the
 * service_role bypasses RLS entirely, so leaking it is leaking the table. A
 * command keeps the master key on one machine.
 *
 * WHERE THE PAIRS LIVE (since 2026-10-14)
 * public.quick_signin_accounts, verified through resolve_pair(email, code).
 * The admin edits rows in the comment panel (Reviewer tab -> Access) and those
 * edits apply immediately; nothing in this repo holds a code any more. This
 * tool writes the same row, plus the one thing the panel cannot do: create the
 * auth account or move its password.
 *
 * THE CODE IS THE ACCOUNT PASSWORD
 * Deliberate: the sign-in paths hand the pair straight to signInWithPassword
 * (or signUp on first use), so a separate secret would be a second thing to
 * keep in sync for no gain. resolve_pair verifies the pairing; Supabase
 * verifies the password.
 *
 * THE BOT ID IS WHY THE PASSWORD MOVE EXISTS
 * The id `bot` (typed where an email goes) signs in as bot@sage.com, a real
 * account, so it can comment. Changing its code in the panel changes the ROW
 * immediately — the gate and middleware re-resolve it — but the ACCOUNT
 * password is only moved here:
 *
 *   SUPABASE_SERVICE_ROLE_KEY=... node tooling/add-pair.js bot@sage.com <new code>
 *
 * on the host that holds the key. Until then the pair resolves but sign-in
 * refuses, which is the safe direction.
 */

const fs = require('fs');

const DEFAULT_URL = 'https://ltyyzxnxufvkorekglrf.supabase.co';
const TABLE = '/rest/v1/quick_signin_accounts';
const argv = process.argv.slice(2);
const has = f => argv.includes(f);
const val = (f, d) => { const i = argv.indexOf(f); return i === -1 ? d : argv[i + 1]; };

const isEmail = s => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s);

function makeCode() {
  // 10 digits from crypto, not Math.random. Readable aloud over a call, and
  // long enough that it is not worth guessing. (5 bytes keeps the value under
  // 2^53 so the modulo does not lose precision.)
  const c = require('crypto').randomBytes(5).readUIntBE(0, 5) % 10000000000;
  return String(c).padStart(10, '0');
}

// Pure paths, kept small so --selftest can cover them offline. PostgREST wants
// the filter value URL-encoded, or a plus-tag in an address becomes a space.
const listPath = () => TABLE + '?select=email,code&order=email.asc';
const filterPath = (email, select) => TABLE + '?'
  + (select ? 'select=email,code&' : '')
  + 'email=eq.' + encodeURIComponent(email);
const upsertPath = () => TABLE + '?on_conflict=email';

// ------------------------------------------------------------------ supabase --

function serviceKey() {
  if (process.env.SUPABASE_SERVICE_ROLE_KEY) return process.env.SUPABASE_SERVICE_ROLE_KEY;
  const f = process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
  if (f && fs.existsSync(f)) {
    const m = /^\s*(?:SUPABASE_SERVICE_ROLE_KEY\s*=\s*)?(\S+)\s*$/.exec(fs.readFileSync(f, 'utf8').trim());
    if (m) return m[1];
  }
  return null;
}

async function api(base, key, method, path_, body, extraHeaders) {
  const res = await fetch(`${base}${path_}`, {
    method,
    headers: Object.assign(
      { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
      extraHeaders || {},
    ),
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch (e) { /* not json */ }
  if (!res.ok) {
    const why = (json && (json.msg || json.message || json.error_description)) || `HTTP ${res.status}`;
    throw new Error(why);
  }
  return json;
}

/** Create the user, or reset the password if it already exists. */
async function upsertUser(base, key, email, password) {
  const list = await api(base, key, 'GET', '/auth/v1/admin/users?per_page=200');
  const hit = (list.users || []).find(u => (u.email || '').toLowerCase() === email.toLowerCase());
  if (!hit) {
    await api(base, key, 'POST', '/auth/v1/admin/users', { email, password, email_confirm: true });
    return 'created';
  }
  await api(base, key, 'PUT', `/auth/v1/admin/users/${hit.id}`, { password, email_confirm: true });
  return 'password reset';
}

// -------------------------------------------------------------------- main ---

async function main() {
  if (has('--selftest')) return selftest();

  const key = serviceKey();
  if (!key) {
    console.error('  no SUPABASE_SERVICE_ROLE_KEY, and no SUPABASE_SERVICE_ROLE_KEY_FILE readable.');
    console.error('  the pairs live in Supabase now, so this tool always needs the service');
    console.error('  key — the panel (Reviewer tab -> Access) is the keyless editor.');
    process.exitCode = 1;
    return;
  }
  const base = val('--url', process.env.SUPABASE_URL || DEFAULT_URL);

  if (has('--list')) {
    const rows = await api(base, key, 'GET', listPath());
    console.log('  ' + (rows.length ? 'ids with quick sign-in:' : 'nobody yet'));
    for (const r of rows) console.log(`    ${r.email}  code ${r.code}`);
    return;
  }

  const email = val('--email', argv.find(a => !a.startsWith('--')) || '');
  if (!email || !isEmail(email)) {
    console.error('  usage: node tooling/add-pair.js <email> [code] [--remove]');
    console.error('         node tooling/add-pair.js --list | --selftest');
    console.error('  needs SUPABASE_SERVICE_ROLE_KEY (or SUPABASE_SERVICE_ROLE_KEY_FILE).');
    process.exitCode = 1;
    return;
  }
  const lower = email.toLowerCase();

  if (has('--remove')) {
    await api(base, key, 'DELETE', filterPath(lower, false));
    console.log(`  removed ${lower}`);
    console.log('  an auth account (if any) stays; with no row, resolve_pair refuses its pair.');
    return;
  }

  const code = val('--code', argv.find(a => /^\d{8,}$/.test(a))) || makeCode();
  await api(base, key, 'POST', upsertPath(), { email: lower, code }, { Prefer: 'resolution=merge-duplicates' });
  const how = await upsertUser(base, key, lower, code);
  console.log(`  paired ${lower}`);
  console.log(`  code:   ${code}`);
  console.log(`  user:   ${how}`);
}

// ---------------------------------------------------------------- selftest ---

function selftest() {
  let pass = 0, fail = 0;
  const t = (n, got, want) => {
    const a = JSON.stringify(got), b = JSON.stringify(want);
    if (a === b) { pass++; console.log(`  ok    ${n}`); }
    else { fail++; console.log(`  FAIL  ${n}\n          got  ${a}\n          want ${b}`); }
  };

  console.log('paths the REST calls use');
  t('the list asks for both columns, ordered', listPath(),
    TABLE + '?select=email,code&order=email.asc');
  t('a filtered read selects the columns too', filterPath('a@sage.com', true),
    TABLE + '?select=email,code&email=eq.a%40sage.com');
  t('a filter encodes a plus-tag, not a space', filterPath('a+bot@sage.com', false),
    TABLE + '?email=eq.a%2Bbot%40sage.com');
  t('the upsert says which column decides', upsertPath(), TABLE + '?on_conflict=email');

  console.log('\ninput checking');
  t('a real address is accepted', isEmail('someone@sage.com'), true);
  t('a missing @ is refused', isEmail('someone.sage.com'), false);
  t('an address with a space is refused', isEmail('some one@sage.com'), false);

  console.log('\ngenerated codes');
  t('ten digits', /^\d{10}$/.test(makeCode()), true);
  t('two in a row differ', makeCode() === makeCode(), false);

  console.log('\n' + pass + ' passed, ' + fail + ' failed');
  process.exit(fail ? 1 : 0);
}

if (has('--selftest')) selftest();
else main().catch(e => { console.error('  ' + e.message); process.exitCode = 1; });

module.exports = { isEmail, makeCode, listPath, filterPath, upsertPath };

