      delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE; fsx.unlinkSync(f);
      return [r.privileged, r.key]; })(), [true, 'sb_secret_testvalue']);
  t('a KEY=value file is accepted too, not only a bare key',
    (() => { const fsx = require('fs'), os = require('os'), p = require('path');
      const f = p.join(os.tmpdir(), '.pk-test-key2'); fsx.writeFileSync(f, 'SUPABASE_SERVICE_ROLE_KEY=sb_secret_v2\n');
      const a = process.env.SUPABASE_SERVICE_ROLE_KEY;
      process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = f;
      const r = supabaseConfig().key;
      if (a !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY = a; else delete process.env.SUPABASE_SERVICE_ROLE_KEY;
      delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE; fsx.unlinkSync(f);
      return r; })(), 'sb_secret_v2');
  t('a missing key file does not masquerade as a key', (() => {
    const a = process.env.SUPABASE_SERVICE_ROLE_KEY, c = process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
    delete process.env.SUPABASE_SERVICE_ROLE_KEY;
    process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = '/nonexistent/no-such-key-file';
    const k = supabaseConfig().key;
    if (a !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY = a; else delete process.env.SUPABASE_SERVICE_ROLE_KEY;
    if (c !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = c; else delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
    return /^sb_publishable_/.test(k || ''); })(), true);

  console.log('\nthe credential must be inspected, not merely located');
  t('sb_publishable_ is NOT privileged — this is the exact paste that got through',
    isPrivilegedKey('sb_publishable_iq-6QsWcYzCKHM6FOOHOuw_vZttKZDR'), false);
  t('sb_secret_ IS privileged', isPrivilegedKey('sb_secret_abc123'), true);
  t('a legacy anon JWT is not privileged',
    isPrivilegedKey('eyJhbGciOiJIUzI1NiJ9.' + Buffer.from(JSON.stringify({ role: 'anon' })).toString('base64') + '.sig'), false);
  t('a legacy service_role JWT IS privileged',
    isPrivilegedKey('eyJhbGciOiJIUzI1NiJ9.' + Buffer.from(JSON.stringify({ role: 'service_role' })).toString('base64') + '.sig'), true);
  t('an unrecognised shape fails CLOSED', isPrivilegedKey('some-random-string'), false);
  t('undefined is not privileged', isPrivilegedKey(undefined), false);
  t('a publishable key in the key FILE does not satisfy the guard',
    (() => { const fsx = require('fs'), os = require('os'), p = require('path');
      const f = p.join(os.tmpdir(), '.pk-pub'); fsx.writeFileSync(f, 'sb_publishable_iq-6QsWcYzCKHM6FOOHOuw_vZttKZDR\n');
      const a = process.env.SUPABASE_SERVICE_ROLE_KEY, c = process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
      delete process.env.SUPABASE_SERVICE_ROLE_KEY; process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = f;
      const r = supabaseConfig();
      if (a !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY = a; else delete process.env.SUPABASE_SERVICE_ROLE_KEY;
      if (c !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = c; else delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
      fsx.unlinkSync(f);
      return [r.privileged, r.keyKind]; })(), [false, 'not-privileged']);

  console.log('\n' + pass + ' passed, ' + fail + ' failed');
  process.exit(fail ? 1 : 0);
}
if (has('--selftest')) selftest();

// -------------------------------------------------------------------- main ---
async function once(slug) {
  const cfg = supabaseConfig();
  if (!cfg.key) {
    console.error(`  cannot read comments: ${cfg.why || 'no Supabase key available'}`);
    process.exitCode = 1; return;
  }

  // REFUSE, DO NOT POLL. If threading is live and this is not a privileged key,
  // the read below returns [] whether or not there is work, and reporting "no
  // /bot comments" would be a lie that reads like good news.
  if (!cfg.privileged) {
    const probe = await probeThreading(cfg);
    if (probe.threaded) {
      console.error('  REFUSING TO POLL: threading is live and this key is not privileged.');
      console.error(`    the key in use is: ${cfg.keyKind}`);
      console.error('    20261014090000 narrowed page_comments SELECT to signed-in users.');
      console.error('    The publishable key now reads ZERO rows with NO error, so a poll here');
      console.error('    would report "no /bot comments" forever while dispatching nothing.');
      console.error('    Fix: set SUPABASE_SERVICE_ROLE_KEY_FILE to a 0600 file holding the');
      console.error('    project SECRET key (Dashboard -> Project Settings -> API Keys -> the');
      console.error('    sb_secret_ one, NOT the sb_publishable_ one shown beside it).');
      process.exitCode = 1;
      return;
    }
    console.log(`  using the ${cfg.keyKind} key — threading is not applied yet, so reads are still open`);
  }

  const got = await fetchBotComments(cfg, slug);
  if (got.error) { console.error(`  cannot read comments: ${got.error}`); process.exitCode = 1; return; }
  if (!got.rows.length) { console.log('  no /bot comments'); return; }
  console.log(`  ${got.rows.length} /bot comment(s)`);

  const notify = has('--notify');
  // One canonical read of the store per pass, so a comment already dealt with is
  // recognised as such instead of being re-packed and re-dispatched every tick.
  let index = { ok: false, map: new Map() };
  if (!notify) {
    index = bugIndex();
    if (!index.ok) { console.error(`  cannot read the bug store: ${index.why}`); process.exitCode = 1; return; }
  }
  let anyFail = false;
  for (const c of got.rows) {
    const parsed = parseBot(c.body);
    if (!parsed) { console.log(`  ${c.id.slice(0, 8)} not an instruction — skipped`); continue; }
    const r = notify ? notifyVmBot(parsed, c, slug) : fileAndDispatch(c, parsed, slug, index);
    if (!r.ok) anyFail = true;
    const okMark = r.ok ? (r.stage === 'skip' ? 'skip' : 'ok  ') : 'FAIL';
    const card = ' ' + cardLabel(r.publicN, r.id);
    // The notify verdict is printed, never just recorded. result.notified was
    // set and never read, which meant a notice that failed to send looked
    // exactly like one that sent — the same silent-success shape learning 103
    // is about, introduced by the fix for it.
    const sent = r.notified === false ? 'NOT SENT — ' + (r.notifyWhy || 'unknown') : (r.to ? ' → ' + r.to : '');
    console.log(`  ${okMark} ${c.id.slice(0, 8)} ${r.stage}${card}`
      + (r.ok
        ? (r.already ? ` — already ${r.already}` : sent)
        : ` — ${(r.why || r.err || ('exit ' + r.code) || '').split('\n')[0].slice(0, 120)}`));
  }
  // A notify pass that silently delivered nothing is the failure this file exists
  // to avoid, so it is an exit code and not a log line.
  if (anyFail) process.exitCode = 1;
}

(async () => {
  const slug = val('--page', DEFAULT_PAGE);
  const once$ = has('--once');
  const interval = Number(val('--interval', 300)) * 1000;

  if (once$) { await once(slug); return; }
  if (has('--watch')) {
    console.log(`  polling ${slug} every ${interval / 1000}s — Ctrl-C to stop`);
    for (;;) { try { await once(slug); } catch (e) { console.error('  ' + e.message); } await new Promise((r) => setTimeout(r, interval)); }
  }
  console.log('usage: node tooling/bot-dispatch.js [--once] [--watch] [--page <slug>] [--interval <s>]');
})();

module.exports = { parseBot, claimTitle, packFields };

