#!/usr/bin/env node
// /bot poller — hands a page comment to a Health-tracker agent.
//
// WHY A POLLER AND NOT A WEBHOOK
// A webhook needs a public endpoint, and this site is static: vercel.json has no
// functions and AGENTS.md forbids adding a build step. So a browser cannot push
// anywhere. It writes the comment (which it already can) and something with
// outbound access comes and gets it. The same reasoning as sync-watch.js, which
// polls Figma for the same reason.
//
// WHERE IT RUNS
// On the VM, beside the bots. SSH as ubuntu@51.254.217.163 works and ~/bot-host is
// the Health-tracker checkout. It also runs here read-only against the same REST
// endpoint, which is how it is tested.
//
//   node tooling/bot-dispatch.js --once      poll once
//   node tooling/bot-dispatch.js --watch     poll every --interval seconds
//   node tooling/bot-dispatch.js --selftest  offline, no network
//
//   add --notify to hand the instruction to the VM bot over Telegram instead of
//   filing the card here. See "the notification path" below for why that is the
//   default shape to grow toward: it needs no credential off-box, and a human
//   sees the instruction. Without --notify this file still does create -> pack ->
//   dispatch itself, which is the right thing when it runs beside the bots.
//
// THE CLAIM IS ATOMIC, AND IT IS NOT IN THIS FILE
// Filing the card is what claims the comment. POST /api/bugs dedupes on title_key,
// so `page:<slug> comment:<uuid>` returns 200 {existing:true} for a comment already
// filed and creates nothing. That is an atomic conditional write at the store,
// which is the whole point of the Idempotent Consumer pattern: a check-then-set in
// a poller has a window where two overlapping passes both pass the check.
//
// The claim is atomic, and it is not in this file. Filing the card is what claims
// the comment: the store dedupes on title_key, so `page:<slug> comment:<uuid>`
// returns the existing card and creates nothing. That is an atomic conditional
// write at the store, which is the whole point of the Idempotent Consumer pattern:
// a check-then-set in a poller has a window where two overlapping passes both
// pass the check.
//
//   What I had wrong, and what this now says instead: "create is idempotent" was
//   true and useless on its own. `pack` overwrites the defect pack and resets the
//   card's state unconditionally, and it is the reset that re-opens the dispatch
//   guard — so a poller that re-created and re-packed every recent comment would
//   have unblocked a SECOND agent on work already in flight, every five minutes.
//   So the store is read once per pass (bugIndex) and a comment whose card is
//   already past `packed` is skipped, not re-packed. The card is the record; the
//   poller reads it rather than keeping a state file of its own.
//
//   The trap: `create` alone is not dispatch. run-coding-dispatch.sh --task= is
//   refused by packCheck (exit 1) for an unpacked card, and --ticket= refuses a
//   card with no defect (exit 3). All four of pack's fields are mandatory.
//
//   create's RESPONSE is not trustworthy on the existing path: it reports
//   public_n 0 and state "new" for a card that is really #58 and in_fix. Only
//   bugctl list is believed. That is a bugctl defect, filed as its own card.

'use strict';
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const { pathToFileURL } = require('url');

const ROOT = path.join(__dirname, '..');

const argv = process.argv.slice(2);
const has = f => argv.includes(f);
const val = (f, d) => { const i = argv.indexOf(f); return i === -1 ? d : argv[i + 1]; };

const DEFAULT_PAGE = 'customer-payment-services';

// -------------------------------------------------------------- the parser --
//
// MUST match components/page-comments.js parseBot. They drifted once and the
// panel announced one agent while the dispatcher posted to another. An `@` is
// required before a target, because an optional bare word is greedy: "/bot fix
// the second card" would parse target="fix" and eat the first word of every
// multi-word instruction.
function parseBot(body) {
  const text = body || '';
  const m = /^\s*\/bot(?:\s+@([a-z0-9_-]+))?\s+([\s\S]+)$/i.exec(text);
  if (!m) return null;
  if (!m[1] && /^\s*\/bot\s+@/i.test(text)) return null;
  return { target: m[1] || null, instruction: m[2].trim() };
}

/**
 * The deterministic title that IS the claim.
 *
 * Two runs of this poller over the same comment produce the same title_key, so the
 * second is refused by the store rather than by anything in this process. It must
 * not contain the instruction: the instruction changes if someone edits the
 * comment, and an edit must not become a second claim.
 */
function claimTitle(slug, commentId) {
  return `page:${slug} comment:${commentId}`;
}

/** Pack's four fields are mandatory and the dispatcher refuses a card without
 *  them, so they are derived rather than left to an operator. */
function packFields(parsed, anchor, slug) {
  const where = anchor ? anchor.replace(/^component:/, '') : 'an unanchored element';
  return {
    component: where,
    observed: `A reviewer left a comment on the ${slug} page, anchored to ${where}.`,
    expected: parsed.instruction,
    criteria:
      'Make the change in the component named above only. Run node tooling/sync-check.js '
      + 'and node tooling/render-check.js, then commit. Report the result back on the '
      + 'comment thread.',
  };
}

// -------------------------------------------------------------- the plumbing --
/**
 * Where the poller reads from.
 *
 * The page's key is a Supabase *publishable* key — it is in the page on purpose,
 * and it is what the browser uses. Reading it from the same place the browser
 * does means a machine with the repo cloned can poll with nothing configured, and
 * there is no second copy of a credential to go stale.
 *
 * That only works while `page_comments` is public-read. It is not, and will not
 * be: 20261014090000 narrows SELECT to `auth.uid() is not null`, which is the
 * stated requirement — sign-in gates the panel for read AND write — and a
 * client-side gate is not a gate.
 *
 * So the poller needs SUPABASE_SERVICE_ROLE_KEY, which bypasses RLS. The publishable
 * key is still the default for a reason worth keeping: it is the one that works
 * without a secret, and probeThreading() below is what stops it being used once it
 * stops working. See there for why "zero rows and no error" is the most dangerous
 * possible outcome for a poller.
 *
 * SUPABASE_SERVICE_ROLE_KEY_FILE is preferred over the bare variable so the key
 * never appears in `systemctl cat`, `ps`, or a unit file in the repo.
 */
/**
 * Is this key actually privileged? A FILE RESOLVING IS NOT THE SAME QUESTION.
 *
 * This exists because the first version of the guard checked only whether
 * SUPABASE_SERVICE_ROLE_KEY_FILE had produced a string, and the publishable key
 * was pasted into that file by mistake. It is the same length, it is the same
 * value that sits in the page HTML, and the poller went green and reported "no
 * /bot comments" — the exact silent failure the guard was written to stop. A
 * guard that can be satisfied by the wrong credential is not a guard.
 *
 * So the key itself is inspected, and an unrecognised shape fails CLOSED:
 *
 *   sb_secret_…      privileged
 *   sb_publishable_…  NOT privileged, by definition
 *   eyJ…             a legacy JWT: decode the payload and read its `role`.
 *                     anon is not service_role, and saying so beats guessing.
 *   anything else    not privileged
 */
function isPrivilegedKey(k) {
  if (!k) return false;
  if (k.startsWith('sb_publishable_')) return false;
  if (k.startsWith('sb_secret_')) return true;
  if (k.startsWith('eyJ')) {
    try {
      const payload = JSON.parse(Buffer.from(k.split('.')[1], 'base64').toString('utf8'));
      return payload.role === 'service_role';
    } catch (e) { return false; }
  }
  return false;
}

function supabaseConfig() {
  let pageKey = null, pageUrl = null;
  try {
    const html = fs.readFileSync(path.join(ROOT, 'ongoing_project', 'cpp', DEFAULT_PAGE, 'index.html'), 'utf8');
    pageKey = (/data-supabase-anon-key="([^"]+)"/.exec(html) || [])[1] || null;
    pageUrl = (/data-supabase-url="([^"]+)"/.exec(html) || [])[1] || null;
  } catch (e) { /* no page to read; env may still carry it */ }

  // Read the secret from a file when one is named, so it never lands in a unit
  // file, in `ps`, or in `systemctl cat`. A 0600 file owned by ubuntu is a
  // smaller thing to get wrong than an environment variable in a committed
  // workflow.
  let fileKey = null;
  const keyFile = process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
  if (keyFile) {
    try {
      const raw = fs.readFileSync(keyFile, 'utf8').trim();
      // Accept either a bare key or KEY=value, because both shapes are in the
      // wild and a file that silently yields '' is worse than no file at all.
      const m = /^\s*(?:SUPABASE_SERVICE_ROLE_KEY\s*=\s*)?(\S+)\s*$/.exec(raw);
      fileKey = m ? m[1] : null;
    } catch (e) {
      if (process.env.SUPABASE_REQUIRE_SECRET === '1') {
        return { url: process.env.SUPABASE_URL || pageUrl, key: null, why: `cannot read SUPABASE_SERVICE_ROLE_KEY_FILE at ${keyFile}: ${e.message}` };
      }
    }
  }

  const privileged = process.env.SUPABASE_SERVICE_ROLE_KEY || fileKey;
  const secret = privileged || process.env.SUPABASE_ANON_KEY || pageKey;
  return {
    url: process.env.SUPABASE_URL || pageUrl || 'https://ltyyzxnxufvkorekglrf.supabase.co',
    key: secret,
    // What the key IS, not where it came from. A file resolving tells you
    // nothing about what is in it, and the publishable key resolved from a
    // perfectly readable 0600 file.
    privileged: isPrivilegedKey(privileged),
    keyKind: privileged
      ? (isPrivilegedKey(privileged) ? 'service_role' : 'not-privileged')
      : (isPrivilegedKey(secret) ? 'service_role' : 'publishable'),
  };
}

/**
 * Has the threading migration been applied?
 *
 * THIS EXISTS BECAUSE OF THE WORST POSSIBLE POLLER FAILURE.
 *
 * `select id from page_comments limit 1` returns `[]` both when the table is
 * genuinely empty and when RLS is hiding every row from this key. There is no
 * error, no status code, no warning. So once 20261014090000 narrows SELECT to
 * signed-in users, a poller still holding the publishable key reads "no /bot
 * comments" forever, exits 0, and stops dispatching — with nothing anywhere
 * saying why. The timer would look perfectly healthy.
 *
 * `parent_id` exists if and only if that migration ran, and selecting a column
 * that does not exist is a hard 400 rather than an empty array. That asymmetry
 * is the only thing that distinguishes "nothing to do" from "you cannot see
 * anything", and it is the only reason this function exists.
 */
async function probeThreading(cfg) {
  if (!cfg.key) return { threaded: false, why: 'no key' };
  const url = `${cfg.url}/rest/v1/page_comments?select=parent_id&limit=1`;
  try {
    const res = await fetch(url, { headers: { apikey: cfg.key, Authorization: `Bearer ${cfg.key}` } });
    if (res.status === 400) return { threaded: false }; // column absent -> not applied
    if (!res.ok) return { threaded: false, why: `HTTP ${res.status}` };
    return { threaded: true };
  } catch (e) {
    return { threaded: false, why: e.message };
  }
}

async function fetchBotComments(cfg, slug) {
  if (!cfg.key) return { error: 'no SUPABASE_SERVICE_ROLE_KEY (or ANON_KEY) in the environment' };
  const q = new URLSearchParams({
    select: 'id, body, anchor, created_at',
    page_slug: `eq.${slug}`,
    order: 'created_at.desc',
    limit: '25',
  });
  // body is filtered by the partial index page_comments_bot_body_idx. The
  // supabase-js query builder cannot express `like`, so this is a raw fetch.
  const url = `${cfg.url}/rest/v1/page_comments?${q}&body=like.%2Fbot%25`;
  const res = await fetch(url, { headers: { apikey: cfg.key, Authorization: `Bearer ${cfg.key}` } });
  if (!res.ok) return { error: `HTTP ${res.status} — ${(await res.text()).slice(0, 160)}` };
  const rows = await res.json();
  return { rows: Array.isArray(rows) ? rows : [] };
}

function bugctl(args, opts = {}) {
  const repo = process.env.BOT_HOST_DIR || path.join(ROOT, '..', 'Health-tracker');
  if (!fs.existsSync(path.join(repo, 'scripts', 'bugctl.mjs'))) {
    return { ok: false, why: `no bugctl at ${repo} (set BOT_HOST_DIR)` };
  }
  const r = spawnSync('node', [path.join(repo, 'scripts', 'bugctl.mjs'), ...args],
    { encoding: 'utf8', cwd: repo, timeout: 60000, ...opts });
  return { ok: r.status === 0, code: r.status, out: (r.stdout || '').trim(), err: (r.stderr || '').trim() };
}

/**
 * title -> { public_n, state, queue }, read once per pass.
 *
 * NOT from `bugctl create`. On the existing path create returns a stub: for a
 * card that was really #58 and in_fix it reported `public_n: 0`, `state: "new"`
 * and `queue: "ready"`, at both the top level and inside work_item. An
 * idempotent consumer that trusts that response re-packs a card an agent is
 * already working on, and `pack` overwrites the defect and resets the state —
 * which is exactly what un-blocks the dispatch guard for a second agent.
 *
 * So the state is read from the canonical list, once, and trusted over create.
 * Keyed by title because that is the only handle a page comment has: its
 * deterministic title_key.
 */
function bugIndex() {
  const r = bugctl(['list', '--json']);
  if (!r.ok) return { ok: false, why: r.err || `bugctl list exit ${r.code}` };
  let rows;
  try {
    rows = JSON.parse(r.out.slice(r.out.indexOf('{'))).rows;
  } catch (e) {
    return { ok: false, why: `could not read bugctl list: ${r.out.slice(0, 120)}` };
  }
  const map = new Map();
  for (const row of (rows || [])) {
    if (row && row.title) {
      map.set(row.title, {
        tag_id: row.tag_id || null,
        public_n: row.public_n || null,
        state: row.state || row.status || null,
        queue: row.queue || null,
      });
    }
  }
  return { ok: true, map };
}

/**
 * create -> pack -> dispatch. All three, in that order.
 *
 * `create` is idempotent by title_key, so re-running costs nothing. `pack` is the
 * one step that is NOT idempotent: POST /api/bugs/:id/defect overwrites item.defect
 * unconditionally. It is safe here only because `create` on an already-claimed
 * comment returns the EXISTING id and we skip straight to dispatch, whose own PID
 * lock refuses a second run.
 */
function fileAndDispatch(comment, parsed, slug, index) {
  const title = claimTitle(slug, comment.id);
  const known = index && index.ok ? index.map.get(title) || null : null;

  // THE CLAIM, and the reason this function is safe to run every five minutes.
  //
  // Read the card BEFORE creating anything. If it is already there and is past
  // `packed`, this comment has been dealt with: an agent is on it, or it is
  // awaiting verification, or it is done. Re-packing it would overwrite the
  // defect pack and reset the state, which is what lets the dispatch guard
  // admit a second agent for work already in flight.
  if (known) {
    return {
      stage: 'skip', ok: true, already: known.state,
      id: known.tag_id || null, publicN: known.public_n,
      why: `already ${known.state || 'filed'} — not re-filed`,
    };
  }

  const created = bugctl(['create', '--title', title, '--json']);
  if (!created.ok) return { stage: 'create', ...created };

  let id = null;
  try {
    const j = JSON.parse(created.out.slice(created.out.indexOf('{')));
    id = j.id || j.tag_id || j.public_n;
  } catch (e) { /* fall through to the error below */ }
  if (!id) return { stage: 'create', ok: false, why: `could not read an id from: ${created.out.slice(0, 160)}` };
  // create's own public_n is unusable (see bugIndex), so the canonical list is
  // asked again. One list per pass, not one per comment.
  const publicN = index && index.ok && index.map.get(title)
    ? index.map.get(title).public_n
    : null;

  const f = packFields(parsed, comment.anchor, slug);
  const packed = bugctl(['pack', '--id', String(id),
    '--component', f.component, '--observed', f.observed,
    '--expected', f.expected, '--criteria', f.criteria, '--json']);
  if (!packed.ok) return { stage: 'pack', id, ...packed };

  // --foreground is what makes the exit code meaningful: it says whether the
  // agent actually started. Under a systemd timer that is the wrong trade —
  // Type=oneshot stays "activating" for the whole dispatch, so the unit cannot
  // tick again, and a hung dispatch stops the poller entirely. --detach lets go
  // and takes the card + the Telegram notice as the signal instead.
  const dispatchArgs = [`--ticket=#${id}`];
  if (!has('--detach')) dispatchArgs.push('--foreground');
  const dispatched = spawnSync('bash',
    [path.join(process.env.BOT_HOST_DIR || path.join(ROOT, '..', 'Health-tracker'),
      'scripts', 'run-coding-dispatch.sh'), ...dispatchArgs],
    { encoding: 'utf8', cwd: process.env.BOT_HOST_DIR || path.join(ROOT, '..', 'Health-tracker'), timeout: 900000 });
  const result = {
    stage: 'dispatch',
    id,
    publicN,
    ok: dispatched.status === 0,
    code: dispatched.status,
    out: (dispatched.stdout || '').trim().slice(-600),
    err: (dispatched.stderr || '').trim().slice(-400),
  };
  // The notice is reported, never fatal: a card that is filed and dispatched but
  // unsent is still filed, and failing the pass here would make the poller re-run
  // create/pack against a card that already exists.
  if (!has('--quiet-notify')) {
    const card = cardLabel(publicN, id);
  const n = notifyChat(filedNotice(card, parsed, comment, slug, result, has('--detach')));
    result.notified = n.ok;
    if (!n.ok) result.notifyWhy = n.why;
  }
  return result;
}

// ------------------------------------------------------- the notification path --
//
// WHY TELEGRAM AND NOT THE BUG API
// The obvious design was to POST straight to the bug store. That needs a
// credential off-box: bugWriteGuard accepts a token, same-origin, or loopback-only
// when BUG_API_TOKEN is unset — so a poller anywhere but the app box gets 401, and
// withFallback then QUEUES the write, returns queued:true and exits 0. A poller
// that cannot reach the store looks exactly like a poller that filed the work.
//
// The notification route has no such edge. Telegram is outbound-only from here:
// the bot's webhook (https://health-tracker.co.uk/tghook/vm) is what receives,
// and this site never has to accept a POST. The receiving agent already lives on
// the VM, where bugctl works over loopback. So no token is provisioned, nothing
// is provisioned, and the human sees the instruction in Telegram — which is the
// point of a notification rather than a silent write.
//
// WHY IT MUST BE SENT AS A USER, NOT AS THE BOT
// Telegram never delivers a bot's own sendMessage back to it. Sending as
// @VM_19485_bot would put the text in the chat and never wake the bot — it would
// look like it worked. scripts/lib/tg-userbot.mjs sendAsUser() is the existing
// user client; seat-tags.mjs uses the same session for the same reason ("a bot
// cannot set its own tag").
//
// sendAsUser sets no parse_mode, so none of this is Markdown: identifiers with
// underscores (page_comments, customer_payment) reach the bot intact. The
// bot-token path in telegram-send.sh hit exactly that failure and silently fell
// back to plain text.

const VM_BOT_USERNAME = 'VM_19485_bot';
const TG_CHAT_DEFAULT = '6218257274';

/** The text the VM bot receives. Self-contained: its agent has Health-tracker's
 *  context, not sage-prototypes', so the page, the anchor and the comment id all
 *  have to travel in the message. */
function botMessage(parsed, comment, slug) {
  const anchor = comment.anchor ? String(comment.anchor) : 'none (unanchored comment)';
  const lines = [
    'A /bot instruction arrived on the sage-prototypes site.',
    '',
    `repo:   /home/ubuntu/src/work/sage-prototypes`,
    `page:   ongoing_project/cpp/${slug}   (live: https://sage-prototypes.vercel.app/ongoing_project/cpp/${slug}/)`,
    `anchor: ${anchor}`,
    `comment id: ${comment.id}`,
    parsed.target ? `target agent: @${parsed.target}` : 'target agent: none named — you were chosen as the default',
    '',
    `instruction: ${parsed.instruction}`,
    '',
    'File it as a bug card (bugctl create --title "page:' + slug + ' comment:' + comment.id + '"',
    'then pack all four fields, then dispatch), then work it at COMPONENT level so',
    'future instances inherit the fix. Do not patch the page fragment.',
  ];
  return lines.join('\n');
}

/**
 * Hand the instruction to @VM_19485_bot as a user message.
 *
 * Runs on the VM (where the user session lives). Returns the same shape as
 * fileAndDispatch so the caller does not care which path ran.
 */
function notifyVmBot(parsed, comment, slug) {
  const repo = process.env.BOT_HOST_DIR || path.join(ROOT, '..', 'Health-tracker');
  const lib = path.join(repo, 'scripts', 'lib', 'tg-userbot.mjs');
  if (!fs.existsSync(lib)) {
    return { stage: 'notify', ok: false, why: `no tg-userbot at ${lib} (set BOT_HOST_DIR)` };
  }
  const chat = process.env.TG_CHAT_ID || TG_CHAT_DEFAULT;
  const mod = pathToFileURL(lib).href;
  const script = [
    `const m = await import(${JSON.stringify(mod)});`,
    `const s = await m.sendAsUser(${JSON.stringify(chat)}, ${JSON.stringify(botMessage(parsed, comment, slug))});`,
    `console.log(JSON.stringify(s && s.ok !== false ? { ok: true } : { ok: false, why: String(s) }));`,
  ].join('\n');

  const r = spawnSync(process.execPath, ['--input-type=module', '-e', script],
    { encoding: 'utf8', cwd: repo, timeout: 120000 });
  const out = (r.stdout || '').trim();
  const err = (r.stderr || '').trim();
  try {
    const j = JSON.parse(out.slice(out.indexOf('{')));
    if (j.ok) return { stage: 'notify', ok: true, to: `@${VM_BOT_USERNAME}`, chat };
    return { stage: 'notify', ok: false, why: j.why || out.slice(0, 200) };
  } catch (e) {
    return {
      stage: 'notify', ok: false,
      why: err.slice(0, 200) || `exit ${r.status}: ${out.slice(0, 160)}`,
    };
  }
}

/**
 * Tell the human, over Telegram, that a card exists.
 *
 * This is the part that works with nothing provisioned. telegram-send.sh already
 * sends as the live bot token and the delivery is verified; it needs no user
 * session, no teleproto and no credential off the box.
 *
 * telegram-send.sh hardcodes parse_mode=Markdown and has no flag to turn it off,
 * so any message with two underscores fails once and retries as plain text. The
 * retry is invisible but the failed call is not, so Markdown-active characters
 * are escaped here rather than paying for a round trip every time.
 */
function escapeMd(s) {
  return s.replace(/([_*`[\]])/g, '\\$1');
}

function notifyChat(lines) {
  const repo = process.env.BOT_HOST_DIR || path.join(ROOT, '..', 'Health-tracker');
  const sh = path.join(repo, 'scripts', 'telegram-send.sh');
  if (!fs.existsSync(sh)) return { ok: false, why: `no telegram-send.sh at ${sh} (set BOT_HOST_DIR)` };
  const text = escapeMd(String(lines).trim());

  // Pin the sender. Without this, telegram-send.sh falls back to ~/.hermes/.env
  // and every comment arrived from @Health_tracker_159bot, while deploy and push
  // notifications came from @VM_19485_bot — two bots, one system, and no way to
  // tell at a glance which notification you were looking at.
  //
  // Read from a file for the same reason as the Supabase key: `systemctl cat` and
  // `ps` are world-readable, so the token belongs in a 0600 file rather than in
  // the unit or in the repository.
  const env = Object.assign({}, process.env);
  if (!env.TELEGRAM_BOT_TOKEN) {
    const f = process.env.TELEGRAM_BOT_TOKEN_FILE;
    if (f && fs.existsSync(f)) {
      const m = /^\s*(?:TELEGRAM_BOT_TOKEN\s*=\s*)?(\S+)\s*$/.exec(fs.readFileSync(f, 'utf8').trim());
      if (m) env.TELEGRAM_BOT_TOKEN = m[1];
    }
  }

  const r = spawnSync('bash', [sh, `--text=${text}`],
    { encoding: 'utf8', cwd: repo, timeout: 60000, env });
  const out = (r.stdout || '').trim();
  return {
    ok: r.status === 0,
    out: out.slice(-160),
    why: r.status === 0 ? null
      : ((r.stderr || '') + ' ' + out).trim().split('\n').pop().slice(0, 160),
  };
}

/** What a human is shown for a card.
 *
 *  tag_id is what `--id` needs; public_n is what a human needs. Showing someone
 *  "card #tag_mv83i63b_mdu16v" is not a notification, it is a riddle. The public
 *  number wins whenever create reported one, which it always does. */
function cardLabel(publicN, id) {
  return publicN ? '#' + publicN : String(id || '?');
}

/** The post-dispatch notice. Says what happened, where, and what to look at —
 *  a notification that does not name the card is not one. */
function filedNotice(card, parsed, comment, slug, dispatched, detached) {
  const state = !dispatched.ok
    ? 'Dispatch did not exit clean — the card is packed and queued, but nothing started on its own.'
    : detached
      ? 'Dispatched detached: the agent was launched and will push from its own worktree. This card is the thing to watch — it is the only proof the work finished.'
      : 'Dispatched in the foreground. The agent works in its own worktree; watch the card for the commit.';
  return [
    `sage-prototypes: /bot filed as card #${card}`,
    '',
    `page:   ongoing_project/cpp/${slug}`,
    `anchor: ${comment.anchor || 'none (unanchored comment)'}`,
    `ask:    ${parsed.instruction}`,
    '',
    state,
  ].join('\n');
}

// --------------------------------------------------------------- selftests ---
function selftest() {
  let pass = 0, fail = 0;
  const t = (n, got, want) => {
    const a = JSON.stringify(got), b = JSON.stringify(want);
    if (a === b) { pass++; console.log(`  ok    ${n}`); }
    else { fail++; console.log(`  FAIL  ${n}\n          got  ${a}\n          want ${b}`); }
  };

  console.log('the parser must match components/page-comments.js exactly');
  t('an ordinary comment is not an instruction', parseBot('the heading is wrong'), null);
  t('an unqualified /bot keeps the whole instruction',
    parseBot('/bot fix the second card').instruction, 'fix the second card');
  t('the first word is never taken as the target',
    parseBot('/bot fix the second card').target, null);
  t('an @ names the agent', parseBot('/bot @page widen the hero').target, 'page');
  t('a bare @target with no instruction is refused', parseBot('/bot @page'), null);
  t('a path cannot be a target', parseBot('/bot @../etc do it'), null);
  t('undefined is safe', parseBot(undefined), null);

  console.log('\nthe claim is deterministic and instruction-free');
  t('the same comment always yields the same title',
    claimTitle('cpp', 'abc'), claimTitle('cpp', 'abc'));
  t('different comments differ',
    claimTitle('cpp', 'abc') === claimTitle('cpp', 'xyz'), false);
  t('the instruction is NOT in the title — an edit must not re-claim',
    claimTitle('cpp', 'abc').includes('widen'), false);
  t('it is slug-scoped', claimTitle('a', 'x') === claimTitle('b', 'x'), false);

  console.log('\npack needs all four fields, so all four are produced');
  const f = packFields(parseBot('/bot widen it'), 'component:hb05-hero', 'cpp');
  t('component', f.component, 'hb05-hero');
  t('observed carries the anchor', f.observed.includes('hb05-hero'), true);
  t('expected is the instruction', f.expected, 'widen it');
  t('criteria is present and non-empty', f.criteria.length > 20, true);
  t('an unanchored comment still produces a component field',
    packFields(parseBot('/bot x'), null, 'cpp').component.length > 0, true);

  console.log('\nthe two parsers must be the SAME function in behaviour');
  // Loaded out of the component rather than retyped. The two drifted once: the
  // client took a bare word as the target and this did not, so the panel announced
  // one agent and the dispatcher posted to another. Comparing two copies by eye is
  // how that happened.
  const src = fs.readFileSync(path.join(ROOT, 'components/page-comments/page-comments.js'), 'utf8');
  const fn = /function parseBot\(body\) \{[\s\S]*?\n  \}/.exec(src);
  if (!fn) {
    fail++; console.log('  FAIL  could not find parseBot in the component');
  } else {
    const clientParse = new Function('return ' + fn[0].replace('function parseBot', 'function'))();
    const bodies = [
      '/bot fix the second card', '/bot @page widen the hero', '/bot @page',
      '/bot @../etc do it', '/bot', '/bot x', 'the heading is wrong', '',
      '/BOT @Page Do It', '   /bot @a b', '/bot a\nb', '/bot @page fix the\nsecond card',
    ];
    for (const b of bodies) {
      const a = JSON.stringify(parseBot(b));
      const c = JSON.stringify(clientParse(b));
      if (a === c) { pass++; console.log('  ok    agree on ' + JSON.stringify(b)); }
      else { fail++; console.log('  FAIL  DISAGREE on ' + JSON.stringify(b) + '\n          poller   ' + a + '\n          component ' + c); }
    }
  }

  console.log('\nthe notification must carry what the VM bot cannot know on its own');
  const msg = botMessage(parseBot('/bot @vm widen the hero'), { id: 'C-1', anchor: 'component:hb05-hero|sel:.a' }, 'cpp');
  t('it names the page', msg.includes('ongoing_project/cpp/cpp'), true);
  t('it names the anchor verbatim', msg.includes('component:hb05-hero|sel:.a'), true);
  t('it carries the comment id — the dedupe key', msg.includes('C-1'), true);
  t('it names the target agent', msg.includes('@vm'), true);
  t('it demands a component-level fix', /COMPONENT level/i.test(msg), true);
  t('an unanchored comment says so rather than going blank',
    botMessage(parseBot('/bot x'), { id: 'C-2', anchor: null }, 'cpp').includes('unanchored'), true);
  t('the title it tells the agent to use is the claim title',
    msg.includes(claimTitle('cpp', 'C-1')), true);
  t('the message carries no Markdown-sensitive parse_mode dependency',
    msg.includes('_') ? !/parse_mode/.test(msg) : true, true);

  console.log('\nthe notify path must not silently succeed');
  t('a missing tg-userbot is a failure, not a pass',
    (() => { const o = process.env.BOT_HOST_DIR; process.env.BOT_HOST_DIR = '/nonexistent-x';
      const r = notifyVmBot(parseBot('/bot x'), { id: 'c', anchor: null }, 'cpp');
      if (o === undefined) delete process.env.BOT_HOST_DIR; else process.env.BOT_HOST_DIR = o;
      return r.ok; })(), false);

  console.log('\nthe notice must survive Telegram Markdown');
  t('underscores are escaped, so telegram-send.sh does not fail once per send',
    escapeMd('page_comments and ongoing_project/cpp/x').includes('page\\_comments'), true);
  t('asterisks and backticks too', escapeMd('*a* `b`'), '\\*a\\* \\`b\\`');
  t('the notice names the card — an unnamed notice is not a notification',
    filedNotice(57, parseBot('/bot widen it'), { id: 'c', anchor: 'component:x' }, 'cpp', { ok: true })
      .includes('#57'), true);
  t('a failed dispatch is stated, not dressed up as success',
    filedNotice(57, parseBot('/bot x'), { id: 'c', anchor: null }, 'cpp', { ok: false })
      .includes('did not exit clean'), true);
  t('a detached dispatch says "launched", never "finished" — the card is the proof',
    filedNotice(57, parseBot('/bot x'), { id: 'c', anchor: null }, 'cpp', { ok: true }, true)
      .includes('Dispatched detached'), true);
  t('a detached dispatch does not claim the work is done',
    filedNotice(57, parseBot('/bot x'), { id: 'c', anchor: null }, 'cpp', { ok: true }, true)
      .includes('finished. '), false);
  t('the notice names the card by its PUBLIC number, not its tag_id',
    filedNotice(58, parseBot('/bot x'), { id: 'c', anchor: null }, 'cpp', { ok: true })
      .includes('card #58'), true);
  t('a human is shown #public_n whenever create reported one',
    cardLabel(58, 'tag_mv83i63b_mdu16v'), '#58');
  t('a tag_id is the fallback, never the first choice',
    cardLabel(null, 'tag_mv83i63b_mdu16v'), 'tag_mv83i63b_mdu16v');
  t('cardLabel never returns an empty label', cardLabel(null, null), '?');
  t('a missing telegram-send.sh is a failure, not a pass',
    (() => { const o = process.env.BOT_HOST_DIR; process.env.BOT_HOST_DIR = '/nonexistent-x';
      const r = notifyChat('probe');
      if (o === undefined) delete process.env.BOT_HOST_DIR; else process.env.BOT_HOST_DIR = o;
      return r.ok; })(), false);

  console.log('\nthe poller must run with nothing provisioned');
  const cfg = supabaseConfig();
  t('it finds the Supabase url from the page', /^https:\/\/[a-z]+\.supabase\.co$/.test(cfg.url), true);
  t('it finds the publishable key from the same page the browser reads',
    /^sb_publishable_/.test(cfg.key || ''), true);
  t('a machine with the repo cloned can poll with no env at all',
    (() => { const o = { u: process.env.SUPABASE_URL, k: process.env.SUPABASE_ANON_KEY, s: process.env.SUPABASE_SERVICE_ROLE_KEY };
      delete process.env.SUPABASE_URL; delete process.env.SUPABASE_ANON_KEY; delete process.env.SUPABASE_SERVICE_ROLE_KEY;
      const c = supabaseConfig();
      if (o.u === undefined) delete process.env.SUPABASE_URL; else process.env.SUPABASE_URL = o.u;
      if (o.k === undefined) delete process.env.SUPABASE_ANON_KEY; else process.env.SUPABASE_ANON_KEY = o.k;
      if (o.s === undefined) delete process.env.SUPABASE_SERVICE_ROLE_KEY; else process.env.SUPABASE_SERVICE_ROLE_KEY = o.s;
      return /^sb_publishable_/.test(c.key || ''); })(), true);
  t('service_role still wins when set — the escape hatch is intact',
    (() => { const o = process.env.SUPABASE_SERVICE_ROLE_KEY; process.env.SUPABASE_SERVICE_ROLE_KEY = 'svc_test';
      const c = supabaseConfig();
      if (o === undefined) delete process.env.SUPABASE_SERVICE_ROLE_KEY; else process.env.SUPABASE_SERVICE_ROLE_KEY = o;
      return c.key; })(), 'svc_test');

  console.log('\na pass must not re-file a comment that is already being worked');
  const mkIndex = (state) => ({ ok: true, map: new Map([[claimTitle('cpp', 'abc'),
    { tag_id: 'tag_x', public_n: 58, state, queue: 'in_progress' }]]) });
  const c = { id: 'abc', body: '/bot widen it', anchor: 'component:hb05-hero' };
  for (const st of ['new', 'in_fix', 'verifying', 'done']) {
    const r = fileAndDispatch(c, parseBot(c.body), 'cpp', mkIndex(st));
    t(`a card already "${st}" is skipped, not re-packed`, r.stage, 'skip');
  }
  t('skipping is not failing', fileAndDispatch(c, parseBot(c.body), 'cpp', mkIndex('done')).ok, true);
  t('the skip names the state it found', fileAndDispatch(c, parseBot(c.body), 'cpp', mkIndex('in_fix')).already, 'in_fix');
  t('the skip still reports the card number for a human',
    fileAndDispatch(c, parseBot(c.body), 'cpp', mkIndex('in_fix')).publicN, 58);
  t('an UNKNOWN title is not skipped — that is the new-comment case',
    fileAndDispatch({ id: 'zzz', body: '/bot x', anchor: null }, parseBot('/bot x'), 'cpp', mkIndex('done')).stage !== 'skip', true);
  t('a failed index read must not silently file everything',
    fileAndDispatch(c, parseBot(c.body), 'cpp', { ok: false }).stage !== 'skip', true);

  console.log('\nthe poller must not confuse "nothing to do" with "cannot see"');
  t('a privileged key is recognised as privileged', supabaseConfig().privileged, !!process.env.SUPABASE_SERVICE_ROLE_KEY);
  t('the publishable key alone is NOT privileged',
    (() => { const a = process.env.SUPABASE_SERVICE_ROLE_KEY, b = process.env.SUPABASE_ANON_KEY, c = process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
      delete process.env.SUPABASE_SERVICE_ROLE_KEY; delete process.env.SUPABASE_ANON_KEY; delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
      const r = supabaseConfig().privileged;
      if (a !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY = a;
      if (b !== undefined) process.env.SUPABASE_ANON_KEY = b;
      if (c !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = c;
      return r; })(), false);
  t('the key file beats the publishable key, so the secret is really used',
    (() => { const fsx = require('fs'), os = require('os'), p = require('path');
      const f = p.join(os.tmpdir(), '.pk-test-key'); fsx.writeFileSync(f, 'sb_secret_testvalue\n');
      const a = process.env.SUPABASE_SERVICE_ROLE_KEY, b = process.env.SUPABASE_ANON_KEY;
      process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = f; delete process.env.SUPABASE_ANON_KEY;
      const r = supabaseConfig();
      if (a !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY = a; else delete process.env.SUPABASE_SERVICE_ROLE_KEY;
      if (b !== undefined) process.env.SUPABASE_ANON_KEY = b; else delete process.env.SUPABASE_ANON_KEY;
      delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE; fsx.unlinkSync(f);
      return [r.privileged, r.key]; })(), [true, 'sb_secret_testvalue']);
  t('a KEY=value file is accepted too, not only a bare key',
    (() => { const fsx = require('fs'), os = require('os'), p = require('path');
      const f = p.join(os.tmpdir(), '.pk-test-key2'); fsx.writeFileSync(f, 'SUPABASE_SERVICE_ROLE_KEY=sb_secret_v2\n');
      const a = process.env.SUPABASE_SERVICE_ROLE_KEY;
      process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = f;
      const r = supabaseConfig().key;
      if (a !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY = a; else delete process.env.SUPABASE_SERVICE_ROLE_KEY;
      delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE; fsx.unlinkSync(f);
      return r; })(), 'sb_secret_v2');
  t('a missing key file does not masquerade as a key', (() => {
    const a = process.env.SUPABASE_SERVICE_ROLE_KEY, c = process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
    delete process.env.SUPABASE_SERVICE_ROLE_KEY;
    process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = '/nonexistent/no-such-key-file';
    const k = supabaseConfig().key;
    if (a !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY = a; else delete process.env.SUPABASE_SERVICE_ROLE_KEY;
    if (c !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = c; else delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
    return /^sb_publishable_/.test(k || ''); })(), true);

  console.log('\nthe credential must be inspected, not merely located');
  t('sb_publishable_ is NOT privileged — this is the exact paste that got through',
    isPrivilegedKey('sb_publishable_iq-6QsWcYzCKHM6FOOHOuw_vZttKZDR'), false);
  t('sb_secret_ IS privileged', isPrivilegedKey('sb_secret_abc123'), true);
  t('a legacy anon JWT is not privileged',
    isPrivilegedKey('eyJhbGciOiJIUzI1NiJ9.' + Buffer.from(JSON.stringify({ role: 'anon' })).toString('base64') + '.sig'), false);
  t('a legacy service_role JWT IS privileged',
    isPrivilegedKey('eyJhbGciOiJIUzI1NiJ9.' + Buffer.from(JSON.stringify({ role: 'service_role' })).toString('base64') + '.sig'), true);
  t('an unrecognised shape fails CLOSED', isPrivilegedKey('some-random-string'), false);
  t('undefined is not privileged', isPrivilegedKey(undefined), false);
  t('a publishable key in the key FILE does not satisfy the guard',
    (() => { const fsx = require('fs'), os = require('os'), p = require('path');
      const f = p.join(os.tmpdir(), '.pk-pub'); fsx.writeFileSync(f, 'sb_publishable_iq-6QsWcYzCKHM6FOOHOuw_vZttKZDR\n');
      const a = process.env.SUPABASE_SERVICE_ROLE_KEY, c = process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
      delete process.env.SUPABASE_SERVICE_ROLE_KEY; process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = f;
      const r = supabaseConfig();
      if (a !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY = a; else delete process.env.SUPABASE_SERVICE_ROLE_KEY;
      if (c !== undefined) process.env.SUPABASE_SERVICE_ROLE_KEY_FILE = c; else delete process.env.SUPABASE_SERVICE_ROLE_KEY_FILE;
      fsx.unlinkSync(f);
      return [r.privileged, r.keyKind]; })(), [false, 'not-privileged']);

  console.log('\n' + pass + ' passed, ' + fail + ' failed');
  process.exit(fail ? 1 : 0);
}
if (has('--selftest')) selftest();

// -------------------------------------------------------------------- main ---
async function once(slug) {
  const cfg = supabaseConfig();
  if (!cfg.key) {
    console.error(`  cannot read comments: ${cfg.why || 'no Supabase key available'}`);
    process.exitCode = 1; return;
  }

  // REFUSE, DO NOT POLL. If threading is live and this is not a privileged key,
  // the read below returns [] whether or not there is work, and reporting "no
  // /bot comments" would be a lie that reads like good news.
  if (!cfg.privileged) {
    const probe = await probeThreading(cfg);
    if (probe.threaded) {
      console.error('  REFUSING TO POLL: threading is live and this key is not privileged.');
      console.error(`    the key in use is: ${cfg.keyKind}`);
      console.error('    20261014090000 narrowed page_comments SELECT to signed-in users.');
      console.error('    The publishable key now reads ZERO rows with NO error, so a poll here');
      console.error('    would report "no /bot comments" forever while dispatching nothing.');
      console.error('    Fix: set SUPABASE_SERVICE_ROLE_KEY_FILE to a 0600 file holding the');
      console.error('    project SECRET key (Dashboard -> Project Settings -> API Keys -> the');
      console.error('    sb_secret_ one, NOT the sb_publishable_ one shown beside it).');
      process.exitCode = 1;
      return;
    }
    console.log(`  using the ${cfg.keyKind} key — threading is not applied yet, so reads are still open`);
  }

  const got = await fetchBotComments(cfg, slug);
  if (got.error) { console.error(`  cannot read comments: ${got.error}`); process.exitCode = 1; return; }
  if (!got.rows.length) { console.log('  no /bot comments'); return; }
  console.log(`  ${got.rows.length} /bot comment(s)`);

  const notify = has('--notify');
  // One canonical read of the store per pass, so a comment already dealt with is
  // recognised as such instead of being re-packed and re-dispatched every tick.
  let index = { ok: false, map: new Map() };
  if (!notify) {
    index = bugIndex();
    if (!index.ok) { console.error(`  cannot read the bug store: ${index.why}`); process.exitCode = 1; return; }
  }
  let anyFail = false;
  for (const c of got.rows) {
    const parsed = parseBot(c.body);
    if (!parsed) { console.log(`  ${c.id.slice(0, 8)} not an instruction — skipped`); continue; }
    const r = notify ? notifyVmBot(parsed, c, slug) : fileAndDispatch(c, parsed, slug, index);
    if (!r.ok) anyFail = true;
    const okMark = r.ok ? (r.stage === 'skip' ? 'skip' : 'ok  ') : 'FAIL';
    const card = ' ' + cardLabel(r.publicN, r.id);
    // The notify verdict is printed, never just recorded. result.notified was
    // set and never read, which meant a notice that failed to send looked
    // exactly like one that sent — the same silent-success shape learning 103
    // is about, introduced by the fix for it.
    const sent = r.notified === false ? 'NOT SENT — ' + (r.notifyWhy || 'unknown') : (r.to ? ' → ' + r.to : '');
    console.log(`  ${okMark} ${c.id.slice(0, 8)} ${r.stage}${card}`
      + (r.ok
        ? (r.already ? ` — already ${r.already}` : sent)
        : ` — ${(r.why || r.err || ('exit ' + r.code) || '').split('\n')[0].slice(0, 120)}`));
  }
  // A notify pass that silently delivered nothing is the failure this file exists
  // to avoid, so it is an exit code and not a log line.
  if (anyFail) process.exitCode = 1;
}

(async () => {
  const slug = val('--page', DEFAULT_PAGE);
  const once$ = has('--once');
  const interval = Number(val('--interval', 300)) * 1000;

  if (once$) { await once(slug); return; }
  if (has('--watch')) {
    console.log(`  polling ${slug} every ${interval / 1000}s — Ctrl-C to stop`);
    for (;;) { try { await once(slug); } catch (e) { console.error('  ' + e.message); } await new Promise((r) => setTimeout(r, interval)); }
  }
  console.log('usage: node tooling/bot-dispatch.js [--once] [--watch] [--page <slug>] [--interval <s>]');
})();

module.exports = { parseBot, claimTitle, packFields };

